import{_ as e,o as a,c as o,a6 as d}from"./chunks/framework.BrkgobfX.js";const T=JSON.parse('{"title":"流量控制","description":"连接级与流级窗口、WINDOW_UPDATE 语义与初始窗口变更的边界情况。","frontmatter":{"title":"流量控制","description":"连接级与流级窗口、WINDOW_UPDATE 语义与初始窗口变更的边界情况。","source":"https://daiw.org/manual/http2-3/h2-flow-control"},"headers":[],"relativePath":"manual/computer-programming/http2-3/h2-flow-control.md","filePath":"manual/computer-programming/http2-3/h2-flow-control.md"}'),n={name:"manual/computer-programming/http2-3/h2-flow-control.md"};function r(s,t,i,l,c,p){return a(),o("div",null,[...t[0]||(t[0]=[d(`<h1 id="流量控制" tabindex="-1">流量控制 <a class="header-anchor" href="#流量控制" aria-label="Permalink to &quot;流量控制&quot;">​</a></h1><p>连接级与流级窗口、WINDOW_UPDATE 语义与初始窗口变更的边界情况。</p><h2 id="为什么需要" tabindex="-1">为什么需要 <a class="header-anchor" href="#为什么需要" aria-label="Permalink to &quot;为什么需要&quot;">​</a></h2><p>1.1 完全依赖 <strong>TCP 的流量控制</strong>：接收方读得慢，TCP 窗口收缩，发送方自然被限速。</p><p>h2 打破了这个假设——一条 TCP 连接上有几十个流。若只靠 TCP，一个慢消费者（比如客户端把某个大下载的数据攒在内存里没处理）会让<strong>整条连接</strong>的 TCP 窗口关闭，把其他所有流一起憋死。</p><p>于是 h2 在 HTTP 层<strong>重新实现了一套流量控制</strong>，粒度到单个流。</p><h2 id="两级窗口" tabindex="-1">两级窗口 <a class="header-anchor" href="#两级窗口" aria-label="Permalink to &quot;两级窗口&quot;">​</a></h2><p>每个方向上维护两套窗口，<strong>同一个 <code>DATA</code> 帧同时消耗两者</strong>：</p><table tabindex="0"><thead><tr><th>级别</th><th>作用范围</th><th>由谁计</th></tr></thead><tbody><tr><td><strong>连接级</strong></td><td>整条连接（流 ID = 0）</td><td>全部 <code>DATA</code> 帧之和</td></tr><tr><td><strong>流级</strong></td><td>单个流</td><td>该流的 <code>DATA</code> 帧</td></tr></tbody></table><p>发送一个 N 字节载荷的 <code>DATA</code> 帧：连接窗口 −N，且该流窗口 −N。<strong>两者都必须 ≥ N 才允许发送</strong>——任一为 0 即阻塞。</p><p>关键限制：<strong>只有 <code>DATA</code> 帧受流量控制</strong>。<code>HEADERS</code>、<code>SETTINGS</code>、<code>RST_STREAM</code>、<code>PING</code> 等控制帧<strong>不受限</strong>，保证控制信令永远能通过（否则会死锁）。这也意味着巨大的头部无法被流量控制约束，需靠 <code>MAX_HEADER_LIST_SIZE</code> 单独限制。</p><h2 id="窗口参数" tabindex="-1">窗口参数 <a class="header-anchor" href="#窗口参数" aria-label="Permalink to &quot;窗口参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>初始窗口（两级）</td><td><strong>65535</strong> 字节（2^16 − 1）</td></tr><tr><td>流级初始值可调</td><td><code>SETTINGS_INITIAL_WINDOW_SIZE</code></td></tr><tr><td>连接级初始值</td><td><strong>不可</strong>用 SETTINGS 调整，只能靠 <code>WINDOW_UPDATE</code> 增大</td></tr><tr><td>窗口上限</td><td>2^31 − 1</td></tr></tbody></table><p>默认 65535 字节在高带宽延迟积（BDP）链路上是<strong>严重瓶颈</strong>：跨洋 100ms RTT 下，单流吞吐上限约 <code>65535 / 0.1s ≈ 640 KB/s</code>。生产部署几乎都要调大（常见 1–16 MB）——这是 h2 调优的头号参数。</p><h2 id="window-update" tabindex="-1">WINDOW_UPDATE <a class="header-anchor" href="#window-update" aria-label="Permalink to &quot;WINDOW_UPDATE&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-+-------------------------------------------------------------+</span></span>
<span class="line"><span>|R|              Window Size Increment (31)                     |</span></span>
<span class="line"><span>+-+-------------------------------------------------------------+</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li>载荷 4 字节，其中 1 位保留 + 31 位<strong>增量</strong>（不是新的绝对值）。</li><li>流 ID = 0 → 增连接级窗口；非零 → 增该流窗口。</li><li><strong>增量为 0 是错误</strong>：流级 → <code>PROTOCOL_ERROR</code> 的 <code>RST_STREAM</code>；连接级 → 连接错误。</li><li>累加后超过 2^31 − 1 → <code>FLOW_CONTROL_ERROR</code>。</li><li>即使流已进入 <code>half-closed</code>/<code>closed</code>，仍可能收到对端发来的 <code>WINDOW_UPDATE</code>（竞态），<strong>MUST</strong> 容忍。</li></ul><p>接收方通常在把数据交给应用层后立即发 <code>WINDOW_UPDATE</code> 补足窗口。</p><h2 id="initial-window-size-变更的坑" tabindex="-1">INITIAL_WINDOW_SIZE 变更的坑 <a class="header-anchor" href="#initial-window-size-变更的坑" aria-label="Permalink to &quot;INITIAL_WINDOW_SIZE 变更的坑&quot;">​</a></h2><p><code>SETTINGS_INITIAL_WINDOW_SIZE</code> 改变时，<strong>已存在的所有流</strong>的窗口要按差值调整：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>新流级窗口 = 当前窗口 + (新 INITIAL_WINDOW_SIZE - 旧 INITIAL_WINDOW_SIZE)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>两个必须注意的后果：</p><ol><li><strong>窗口可以变成负数</strong>。若已发送 60000 字节、随后对端把初始窗口从 65535 调到 16384，则窗口变为 <code>5535 + (16384 − 65535) = −43616</code>。此时发送方 <strong>MUST</strong> 停止发送，直到 <code>WINDOW_UPDATE</code> 把它拉回正数。<strong>负窗口是合法状态，不是错误。</strong></li><li>该设置<strong>只影响流级</strong>，连接级窗口不受影响。</li></ol><h2 id="死锁风险" tabindex="-1">死锁风险 <a class="header-anchor" href="#死锁风险" aria-label="Permalink to &quot;死锁风险&quot;">​</a></h2><p>流量控制是自己实现的，就有自己造死锁的可能：</p><ul><li>接收方必须<strong>及时</strong>发 <code>WINDOW_UPDATE</code>，否则发送方永久阻塞。</li><li>一个不读数据的应用会让窗口耗尽——服务端应设读超时，必要时 <code>RST_STREAM</code>。</li><li>双方都在等对方的窗口时（如双向大流量的 gRPC 流式调用），实现必须保证控制帧优先发送。</li></ul><h2 id="与-tcp-流量控制的关系" tabindex="-1">与 TCP 流量控制的关系 <a class="header-anchor" href="#与-tcp-流量控制的关系" aria-label="Permalink to &quot;与 TCP 流量控制的关系&quot;">​</a></h2><p>两层<strong>同时生效</strong>，取更严格者：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应用可发送量 = min(h2 连接窗口, h2 流窗口, TCP 拥塞窗口, TCP 接收窗口)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>h2 窗口调得再大也突破不了 TCP 的限制；反之 TCP 再快，h2 窗口没补上也发不出去。调优时两者都要看。</p><h2 id="http-3-的对照" tabindex="-1">HTTP/3 的对照 <a class="header-anchor" href="#http-3-的对照" aria-label="Permalink to &quot;HTTP/3 的对照&quot;">​</a></h2><p>HTTP/3 <strong>删除了这一层</strong>——流量控制下沉到 QUIC 传输层：</p><table tabindex="0"><thead><tr><th>h2</th><th>h3 / QUIC</th></tr></thead><tbody><tr><td><code>WINDOW_UPDATE</code>（流级）</td><td>QUIC <code>MAX_STREAM_DATA</code> 帧</td></tr><tr><td><code>WINDOW_UPDATE</code>（连接级）</td><td>QUIC <code>MAX_DATA</code> 帧</td></tr><tr><td><code>SETTINGS_INITIAL_WINDOW_SIZE</code></td><td>QUIC 传输参数 <code>initial_max_stream_data_*</code></td></tr><tr><td>还额外受 TCP 窗口约束</td><td>QUIC 自己就是传输层，只有一层</td></tr></tbody></table><p>这消除了 h2「HTTP 层与 TCP 层两套流控互相打架」的复杂性——详见 <a href="/Front2Full/manual/computer-programming/http2-3/quic-transport">QUIC 传输层</a>。</p><p>下一篇：<a href="/Front2Full/manual/computer-programming/http2-3/h2-settings-priority">SETTINGS 与优先级</a>。</p>`,35)])])}const g=e(n,[["render",r]]);export{T as __pageData,g as default};
